local _, route = ...
if not route.steps then return end
local step = route.step
local accept, turnin = route.accept, route.turnin
local when, onQuest, ready = route.when, route.onQuest, route.ready

local fuely = route.npc(10136, "化学家弗雷", 1458, 47.5, 73)
local abigail = route.npc(4604, "阿比盖恩·萨叶尔", 1458, 54.8, 38.2)
local tiala = route.npc(40833, "Tiala Whitemane", 2482, 68.85, 50.6)
route.quest[4642] = {"融合软泥怪", 48, {4293, 4294}}
route.quest[97000] = {"Grain of Memory", 54}
route.quest[97001] = {"Sawyer's Legacy", 54}

local function testSamples(id, sample, equipment, x, y, instructions)
    return when(step("幽暗城药剂区 · 检测软泥怪原样",
        { t = "goto", map = 1458, x = x, y = y, text = "测试仪器", note = instructions },
        { t = "turnin", quest = equipment, title = "软泥样本检测", object = equipment == 4661 and 174848 or 175265,
            objName = "测试仪器", map = 1458, x = x, y = y, direct = true, optional = true }),
        onQuest(id), { k = "has", item = sample, n = 1 }, ready(id, true))
end

function route.addOozeField()
    route.append({
        when(step("安戈洛北部 · 融合软泥怪",
            route.optional(route.collect(4642, 12291, "融合的软泥怪样本", 1, 1, route.point(1449, 46.2, 23.9),
                "两人分别找一只原生软泥怪。近身进入战斗后使用堕落软泥怪容器，击杀融合后的巨型软泥怪并拾取样本。用完容器但未拾到，可以先去平台。"))),
            onQuest(4642), ready(4642, true), { k = "has", item = 12288, n = 1 }),
    })
end

function route.addOozeTurnins()
    route.append({
        testSamples(4293, 12230, 4661, 47.9, 73.5,
            "用红色测试仪器检测费伍德原样并打开检测后的容器。产出随机，拿到 5 份被腐化的费伍德样本就可交。"),
        testSamples(4294, 12235, 4561, 47.7, 73.6,
            "用绿色测试仪器检测安戈洛原样并打开检测后的容器。产出随机，拿到 5 份纯净的安戈洛样本就可交。"),
        when(step("幽暗城 · 交费伍德检测品", turnin(4293, fuely)), ready(4293)),
        when(step("幽暗城 · 交安戈洛检测品", turnin(4294, fuely)), ready(4294)),
        when(step("幽暗城 · 交融合样本", turnin(4642, fuely)), ready(4642)),
        when(step("幽暗城军事区 · 交萨叶尔家族账本", turnin(97001, abigail)), onQuest(97001)),
    })
end

local function belowSixty(entry)
    return route.when(entry, { k = "level", op = "<", n = 60 })
end

